// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITetherToken {
    function deprecate(address _upgradedAddress) external;
    function deprecated() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    ITetherToken tetherToken;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        tetherToken = ITetherToken(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        address contractOwner = 0xC6CDE7C39eB2f0F0095F41570af89eFC2C1Ea828;

                // Check initial state
                assertEq(tetherToken.deprecated(), false);

                // Impersonate the owner and call deprecate()
                vm.startPrank(contractOwner);
                tetherToken.deprecate(address(0xdead));
                vm.stopPrank();

                // Verify the state has changed
                assertEq(tetherToken.deprecated(), true);
        assertEq(tetherToken.deprecated(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

